-- ============================================================
-- 8. PLAYLIST GENERATION CRITERIA
-- ============================================================

CREATE TABLE "playlist_generation_criteria" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "playlist_id" BIGINT NOT NULL,
  "target_duration_seconds" INT,
  "included_genres" TEXT[],
  "excluded_genres" TEXT[],
  "included_artist_ids" BIGINT[],
  "excluded_artist_ids" BIGINT[],
  "created_at" TIMESTAMP NOT NULL DEFAULT NOW(),

  FOREIGN KEY ("playlist_id") REFERENCES "playlists" ("id") ON DELETE CASCADE
);

CREATE INDEX "idx_generation_criteria_playlist_id" 
ON "playlist_generation_criteria" ("playlist_id");


-- ============================================================
-- 9. PLAYLIST FUSIONS
-- ============================================================

CREATE TABLE "playlist_fusions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "result_playlist_id" BIGINT NOT NULL,
  "source_playlist_id" BIGINT NOT NULL,
  "fused_at" TIMESTAMP NOT NULL DEFAULT NOW(),

  FOREIGN KEY ("result_playlist_id") REFERENCES "playlists" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("source_playlist_id") REFERENCES "playlists" ("id") ON DELETE CASCADE,
  
  UNIQUE ("result_playlist_id", "source_playlist_id")
);

CREATE INDEX "idx_fusions_result_playlist_id" 
ON "playlist_fusions" ("result_playlist_id");

CREATE INDEX "idx_fusions_source_playlist_id" 
ON "playlist_fusions" ("source_playlist_id");


-- ============================================================
-- 10. PLAYLIST DOWNLOADS (MODE OFFLINE)
-- ============================================================

CREATE TABLE "playlist_downloads" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "playlist_id" BIGINT NOT NULL,
  "downloaded_at" TIMESTAMP NOT NULL DEFAULT NOW(),
  "expires_at" TIMESTAMP NOT NULL,
  "is_active" BOOLEAN NOT NULL DEFAULT TRUE,

  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  FOREIGN KEY ("playlist_id") REFERENCES "playlists" ("id") ON DELETE CASCADE,
  
  UNIQUE ("user_id", "playlist_id")
);

CREATE INDEX "idx_downloads_user_id" 
ON "playlist_downloads" ("user_id");

CREATE INDEX "idx_downloads_expires_at" 
ON "playlist_downloads" ("expires_at");

-- Fonction pour vérifier la limite de 10 playlists téléchargées
CREATE OR REPLACE FUNCTION check_download_limit()
RETURNS TRIGGER AS $$
BEGIN
  IF (SELECT COUNT(*) FROM "playlist_downloads" 
      WHERE "user_id" = NEW."user_id" AND "is_active" = TRUE) >= 10 THEN
    RAISE EXCEPTION 'Limite de 10 playlists téléchargées atteinte pour cet utilisateur';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger pour appliquer la limite
CREATE TRIGGER trg_check_download_limit
BEFORE INSERT ON "playlist_downloads"
FOR EACH ROW
EXECUTE FUNCTION check_download_limit();